struct StBindingNativeSequenceValue
{
    const void *data = nullptr;
    std::size_t count = 0U;
    bool flag = false;
};

enum class StBindingNativeTaggedReferenceTag : std::uint8_t
{
    none = 0,
    kinematics = 1,
    pose = 2,
};

struct StBindingNativeTaggedReferenceValue
{
    const void *data = nullptr;
    StBindingNativeTaggedReferenceTag tag =
        StBindingNativeTaggedReferenceTag::none;
};

template <StBindingFbType Fb, std::uint16_t Pin>
struct StBindingNativePinAccessor
{
    static constexpr bool available = false;
    static constexpr bool registered = false;
    static constexpr StBindingAdapterKind kind =
        StBindingAdapterKind::unresolved;
};

template <>
struct StBindingNativePinAccessor<StBindingFbType::r_trig, 0U>
{
    static constexpr bool available = true;
    static constexpr bool registered = false;
    static constexpr StBindingAdapterKind kind = StBindingAdapterKind::direct;
    using fb_type = fb::RTrig;
    using value_type = std::remove_reference_t<decltype(std::declval<fb_type &>().clk)>;
    static value_type &get(fb_type &instance) noexcept { return instance.clk; }
    static const value_type &get(const fb_type &instance) noexcept { return instance.clk; }
};

