    st_binding_object_write<std::uint8_t>(bytes, 56U, value.value[3].direction_clockwise ? 1U : 0U);
    st_binding_object_write<double>(bytes, 64U, static_cast<double>(value.value[4].zero_position));
    st_binding_object_write<std::uint8_t>(bytes, 72U, value.value[4].direction_clockwise ? 1U : 0U);
    st_binding_object_write<double>(bytes, 80U, static_cast<double>(value.value[5].zero_position));
